// StGit CLI reimplementation
// Original: https://stacked-git.github.io/

use std::env;
use std::ffi::OsString;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

mod aliases;
mod cli;
mod completion;
mod help_texts;
mod subcommand;

fn main() -> ExitCode {
    let args: Vec<OsString> = env::args_os().collect();
    match run(args) {
        Ok(code) => ExitCode::from(code),
        Err(e) => {
            eprintln!("{}", e);
            ExitCode::from(1)
        }
    }
}

fn run(args: Vec<OsString>) -> Result<u8, String> {
    // Drop argv[0]
    let mut args = args.into_iter().skip(1).collect::<Vec<_>>();

    // Parse top-level options
    let mut color_mode: Option<String> = None;
    let mut cwd_stack: Vec<PathBuf> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        let s = a.to_string_lossy();
        if s == "--" {
            args.remove(i);
            break;
        } else if s == "--version" {
            // Apply any -C chdirs (they affect pathspec args, not this)
            apply_chdirs(&cwd_stack)?;
            return Ok(print_version_long());
        } else if s == "--help" {
            apply_chdirs(&cwd_stack)?;
            print!("{}", help_texts::MAIN_FULL);
            return Ok(0);
        } else if s == "-h" {
            apply_chdirs(&cwd_stack)?;
            print!("{}", help_texts::MAIN_SHORT);
            return Ok(0);
        } else if s == "-C" {
            if i + 1 >= args.len() {
                return Err(format!(
                    "error: a value is required for '-C <path>' but none was supplied\n\n\
                     For more information, try '--help'."
                ));
            }
            let path = PathBuf::from(args[i + 1].clone());
            cwd_stack.push(path);
            args.drain(i..=i + 1);
        } else if let Some(v) = strip_option_value(&s, "--color") {
            let v = v.to_string();
            validate_color(&v)?;
            color_mode = Some(v);
            args.remove(i);
        } else if s == "--color" {
            if i + 1 >= args.len() {
                return Err(format!(
                    "error: a value is required for '--color <when>' but none was supplied\n  \
                     [possible values: auto, always, ansi, never]\n\n\
                     For more information, try '--help'."
                ));
            }
            let v = args[i + 1].to_string_lossy().to_string();
            validate_color(&v)?;
            color_mode = Some(v);
            args.drain(i..=i + 1);
        } else if s.starts_with('-') && s != "-" {
            // Unknown top-level option
            return Err(format!(
                "error: unexpected argument '{}' found\n\n\
                 Usage: stg [OPTIONS] <command> [...]\n       \
                 stg [OPTIONS] <-h|--help>\n       \
                 stg --version\n\n\
                 For more information, try '--help'.",
                s
            ));
        } else {
            // Subcommand
            break;
        }
    }

    apply_chdirs(&cwd_stack)?;

    if args.is_empty() {
        // No subcommand supplied: print short help to stderr, exit 1
        eprint!("{}", help_texts::MAIN_SHORT);
        return Ok(1);
    }

    let subcommand_name = args.remove(0).to_string_lossy().into_owned();

    let ctx = cli::Context {
        color: color_mode,
    };

    subcommand::dispatch(&subcommand_name, args, &ctx)
}

fn apply_chdirs(paths: &[PathBuf]) -> Result<(), String> {
    for p in paths {
        let target: PathBuf = if p.is_absolute() {
            p.clone()
        } else {
            match env::current_dir() {
                Ok(cur) => cur.join(p),
                Err(_) => p.clone(),
            }
        };
        if let Err(e) = env::set_current_dir(&target) {
            return Err(format!(
                "error: cannot change to `{}`: {}",
                p.display(),
                map_os_err(&e)
            ));
        }
    }
    Ok(())
}

pub fn map_os_err(e: &std::io::Error) -> String {
    match e.raw_os_error() {
        Some(code) => format!("{} (os error {})", io_error_msg(code), code),
        None => e.to_string(),
    }
}

fn io_error_msg(code: i32) -> &'static str {
    match code {
        2 => "No such file or directory",
        13 => "Permission denied",
        17 => "File exists",
        20 => "Not a directory",
        21 => "Is a directory",
        _ => "I/O error",
    }
}

pub fn strip_option_value<'a>(arg: &'a str, opt: &str) -> Option<&'a str> {
    if let Some(rest) = arg.strip_prefix(opt) {
        if let Some(rest) = rest.strip_prefix('=') {
            return Some(rest);
        }
    }
    None
}

fn validate_color(v: &str) -> Result<(), String> {
    match v {
        "auto" | "always" | "ansi" | "never" => Ok(()),
        _ => Err(format!(
            "error: invalid value '{}' for '--color <when>'\n  \
             [possible values: auto, always, ansi, never]\n\n\
             For more information, try '--help'.",
            v
        )),
    }
}

pub fn print_version_long() -> u8 {
    print!("Stacked Git 2.5.5\n");
    print!("Copyright (C) 2005-2025 StGit authors\n");
    print!("This is free software: you are free to change and redistribute it.\n");
    print!("There is NO WARRANTY, to the extent permitted by law.\n");
    print!("SPDX-License-Identifier: GPL-2.0-only\n");
    match Command::new("git").arg("--version").output() {
        Ok(o) if o.status.success() => {
            let s = String::from_utf8_lossy(&o.stdout);
            let s = s.trim_end_matches('\n');
            println!("{}", s);
        }
        _ => {}
    }
    0
}

pub fn print_version_short() -> u8 {
    println!("stg 2.5.5");
    0
}

