use crate::cli::Context;
use crate::{aliases, completion, help_texts};
use std::ffi::OsString;

// All subcommand names that stg knows about (both native and alias)
pub static NATIVE_COMMANDS: &[&str] = &[
    "branch", "clean", "commit", "completion", "delete", "diff", "edit", "email", "export",
    "files", "float", "fold", "goto", "hide", "id", "import", "init", "log", "name", "new",
    "next", "patches", "pick", "pop", "prev", "pull", "push", "rebase", "redo", "refresh",
    "rename", "repair", "reset", "series", "show", "sink", "spill", "squash", "sync", "top",
    "uncommit", "undo", "unhide", "version", "help",
];

pub static ALIAS_NAMES: &[&str] = &["add", "mv", "resolved", "rm", "status"];

pub fn all_subcommands_str() -> String {
    let mut names: Vec<&str> = NATIVE_COMMANDS.iter().copied().collect();
    for a in ALIAS_NAMES {
        // Insert aliases at end, keep order matching original
        names.push(a);
    }
    // Need to match original order exactly. The executable shows this order (from the error message):
    // branch, clean, commit, completion, delete, diff, edit, email, export, files, float, fold,
    // goto, hide, id, import, init, log, name, new, next, patches, pick, pop, prev, pull, push,
    // rebase, redo, refresh, rename, repair, reset, series, show, sink, spill, squash, sync,
    // top, uncommit, undo, unhide, version, add, mv, resolved, rm, status, help
    let ordered = [
        "branch", "clean", "commit", "completion", "delete", "diff", "edit", "email", "export",
        "files", "float", "fold", "goto", "hide", "id", "import", "init", "log", "name", "new",
        "next", "patches", "pick", "pop", "prev", "pull", "push", "rebase", "redo", "refresh",
        "rename", "repair", "reset", "series", "show", "sink", "spill", "squash", "sync", "top",
        "uncommit", "undo", "unhide", "version", "add", "mv", "resolved", "rm", "status", "help",
    ];
    ordered.join(", ")
}

pub fn dispatch(name: &str, args: Vec<OsString>, ctx: &Context) -> Result<u8, String> {
    // Aliases first
    if let Some(a) = aliases::find(name) {
        return aliases::run_alias(a, args);
    }

    match name {
        "help" => cmd_help(args),
        "version" => cmd_version(args, ctx),
        "completion" => completion::run(args, ctx),
        // Native commands we don't fully implement: handle help and nothing else.
        other => handle_generic(other, args, ctx),
    }
}

fn cmd_help(args: Vec<OsString>) -> Result<u8, String> {
    if args.is_empty() {
        print!("{}", help_texts::MAIN_FULL);
        return Ok(0);
    }
    let target = args[0].to_string_lossy().to_string();
    // help does not accept -h/--help itself
    if target == "-h" || target == "--help" {
        return Err(format!(
            "error: unrecognized subcommand '{}'\n\n\
             Usage: stg [OPTIONS] <command> [...]\n       \
             stg [OPTIONS] <-h|--help>\n       \
             stg --version\n\n\
             For more information, try '--help'.",
            target
        ));
    }
    if let Some(entry) = help_texts::find(&target) {
        print!("{}", entry.full);
        Ok(0)
    } else {
        Err(format!(
            "error: unrecognized subcommand '{}'\n\n\
             Usage: stg [OPTIONS] <command> [...]\n       \
             stg [OPTIONS] <-h|--help>\n       \
             stg --version\n\n\
             For more information, try '--help'.",
            target
        ))
    }
}

fn cmd_version(args: Vec<OsString>, _ctx: &Context) -> Result<u8, String> {
    let mut short = false;
    let mut iter = args.iter();
    while let Some(a) = iter.next() {
        let s = a.to_string_lossy();
        match s.as_ref() {
            "-h" => {
                print!("{}", help_texts::find("version").unwrap().short);
                return Ok(0);
            }
            "--help" => {
                print!("{}", help_texts::find("version").unwrap().full);
                return Ok(0);
            }
            "-s" | "--short" => short = true,
            _ if s.starts_with("--color=") => {
                let v = s.trim_start_matches("--color=");
                if !matches!(v, "auto" | "always" | "ansi" | "never") {
                    return Err(format!(
                        "error: invalid value '{}' for '--color <when>'\n  \
                         [possible values: auto, always, ansi, never]\n\n\
                         For more information, try '--help'.",
                        v
                    ));
                }
            }
            "--color" => {
                if let Some(v) = iter.next() {
                    let v = v.to_string_lossy();
                    if !matches!(v.as_ref(), "auto" | "always" | "ansi" | "never") {
                        return Err(format!(
                            "error: invalid value '{}' for '--color <when>'\n  \
                             [possible values: auto, always, ansi, never]\n\n\
                             For more information, try '--help'.",
                            v
                        ));
                    }
                } else {
                    return Err("error: a value is required for '--color <when>' but none was supplied\n  \
                                [possible values: auto, always, ansi, never]\n\n\
                                For more information, try '--help'.".to_string());
                }
            }
            _ => {
                return Err(format!(
                    "error: unexpected argument '{}' found\n\n\
                     Usage: stg version [OPTIONS]\n\n\
                     For more information, try '--help'.",
                    s
                ));
            }
        }
    }
    if short {
        Ok(crate::print_version_short())
    } else {
        Ok(crate::print_version_long())
    }
}

fn handle_generic(name: &str, args: Vec<OsString>, _ctx: &Context) -> Result<u8, String> {
    // Check if it's a known command
    let entry = match help_texts::find(name) {
        Some(e) => e,
        None => {
            return Err(format!(
                "error: unrecognized subcommand '{}'\n\n\
                 Usage: stg [OPTIONS] <command> [...]\n       \
                 stg [OPTIONS] <-h|--help>\n       \
                 stg --version\n\n\
                 For more information, try '--help'.",
                name
            ));
        }
    };

    // For help flags, print help
    for a in &args {
        let s = a.to_string_lossy();
        if s == "-h" {
            print!("{}", entry.short);
            return Ok(0);
        } else if s == "--help" {
            print!("{}", entry.full);
            return Ok(0);
        }
    }

    // We don't implement most native commands' actual functionality.
    // Defer to a git-based best-effort error message.
    // For commands that are purely informational, error out.
    Err(format!(
        "error: subcommand `{}` is not implemented in this build",
        name
    ))
}
