use crate::cli::Context;
use crate::help_texts;
use std::ffi::OsString;
use std::fs;
use std::path::PathBuf;

const BASH_SCRIPT: &str = include_str!("data/completion_bash.sh");
const FISH_SCRIPT: &str = include_str!("data/completion_fish.fish");
const ZSH_SCRIPT: &str = include_str!("data/completion_zsh.zsh");

pub fn run(args: Vec<OsString>, _ctx: &Context) -> Result<u8, String> {
    // Parse first positional (subcommand)
    let (opts_and_pos, _) = split_subargs(args);
    // Check for help early
    for a in &opts_and_pos {
        let s = a.to_string_lossy();
        if s == "-h" {
            print!("{}", help_texts::find("completion").unwrap().short);
            return Ok(0);
        } else if s == "--help" {
            print!("{}", help_texts::find("completion").unwrap().full);
            return Ok(0);
        }
    }

    // Find subcommand
    let mut it = opts_and_pos.into_iter().peekable();
    let mut output_path: Option<PathBoxed> = None;
    let mut first_positional: Option<String> = None;
    let mut remaining: Vec<OsString> = Vec::new();

    while let Some(a) = it.next() {
        let s = a.to_string_lossy().to_string();
        if first_positional.is_some() {
            remaining.push(a);
            continue;
        }
        if s == "-o" || s == "--output" {
            if let Some(v) = it.next() {
                output_path = Some(PathBoxed(PathBuf::from(v)));
            } else {
                return Err("error: a value is required for '--output <path>' but none was supplied\n\n\
                    For more information, try '--help'.".into());
            }
        } else if let Some(v) = s.strip_prefix("--output=") {
            output_path = Some(PathBoxed(PathBuf::from(v)));
        } else if let Some(v) = s.strip_prefix("-o") {
            if !v.is_empty() {
                output_path = Some(PathBoxed(PathBuf::from(v)));
            } else {
                // Just `-o` already handled above
            }
        } else if s == "--color" {
            if let Some(v) = it.next() {
                validate_color(&v.to_string_lossy())?;
            }
        } else if let Some(v) = s.strip_prefix("--color=") {
            validate_color(v)?;
        } else if s.starts_with('-') {
            return Err(format!(
                "error: unexpected argument '{}' found\n\n\
                 Usage: stg completion [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
                s
            ));
        } else {
            first_positional = Some(s);
        }
    }

    let sub = match first_positional.as_deref() {
        Some(x) => x,
        None => {
            return Err("error: 'stg completion' requires a subcommand but one was not provided\n  \
                        [subcommands: bash, fish, zsh, list, man, help]\n\n\
                        Usage: stg completion [OPTIONS] <COMMAND>\n\n\
                        For more information, try '--help'.".into());
        }
    };

    match sub {
        "bash" => emit(BASH_SCRIPT, output_path.as_ref()),
        "fish" => emit(FISH_SCRIPT, output_path.as_ref()),
        "zsh" => emit(ZSH_SCRIPT, output_path.as_ref()),
        "list" => completion_list(remaining),
        "man" => Err("error: completion man not implemented in this build".to_string()),
        "help" => {
            if let Some(target) = remaining.first().map(|a| a.to_string_lossy().into_owned()) {
                match target.as_str() {
                    "bash" | "fish" | "zsh" | "list" | "man" | "help" => {
                        // We don't have distinct help texts here; fall back to completion help
                        print!("{}", help_texts::find("completion").unwrap().full);
                        Ok(0)
                    }
                    other => Err(format!(
