    while let Some(a) = iter.next() {
        let s = a.to_string_lossy().to_string();
        if s == "-h" {
            // Use generic completion help as a fallback; actual subcommand help has its own text
            return Ok(emit_help_for_shell(name, true));
        } else if s == "--help" {
            return Ok(emit_help_for_shell(name, false));
        } else if s == "-o" || s == "--output" {
            if let Some(v) = iter.next() {
                output = Some(PathBuf::from(v));
            } else {
                return Err(StgError::new(format!(
                    "error: a value is required for '--output <path>' but none was supplied\n\n\
                     Usage: stg completion {} [OPTIONS]\n\n\
                     For more information, try '--help'.",
                    name
                )));
            }
        } else if let Some(v) = s.strip_prefix("--output=") {
            output = Some(PathBuf::from(v));
        } else if let Some(v) = s.strip_prefix("-o") {
            if !v.is_empty() {
                output = Some(PathBuf::from(v));
            }
        } else if s == "--color" {
            if let Some(v) = iter.next() {
                crate::validate_color(&v.to_string_lossy())?;
            }
        } else if let Some(v) = s.strip_prefix("--color=") {
            crate::validate_color(v)?;
        } else {
            return Err(StgError::new(format!(
                "error: unexpected argument '{}' found\n\n\
                 Usage: stg completion {} [OPTIONS]\n\n\
                 For more information, try '--help'.",
                s, name
            )));
        }
    }

    if let Some(p) = output {
        fs::write(&p, content)
            .map_err(|e| StgError::new(format!("error: cannot write `{}`: {}", p.display(), e)))?;
    } else {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(content.as_bytes());
    }
    Ok(0)
}

fn emit_help_for_shell(_shell: &str, _short: bool) -> u8 {
    // We embed the same generic completion full help as a placeholder.
    // In practice the shell-specific subcommand help is shown for --help/-h,
    // but we don't differentiate here.
    print!("{}", help_texts::find("completion").unwrap().full);
    0
}

fn list_subcommand(args: Vec<OsString>, _output: Option<PathBuf>) -> Result<u8, StgError> {
    // Parse options: --style, -o/--output, --color, then subcommand
    let mut iter = args.into_iter();
    let mut style = String::from("name-only");
    let mut output: Option<PathBuf> = _output;
    let mut subcommand: Option<String> = None;

    while let Some(a) = iter.next() {
        let s = a.to_string_lossy().to_string();
        if s == "-h" || s == "--help" {
            print!("{}", generic_list_help());
            return Ok(0);
