        } else if s.starts_with('-') && s != "-" {
            return Err(StgError::new(format!(
                "error: unexpected argument '{}' found\n\n\
                 Usage: stg completion list [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
                s
            )));
        } else {
            subcommand = Some(s);
            break;
        }
    }

    if !matches!(style.as_str(), "name-only" | "asciidoc" | "fish" | "zsh") {
        return Err(StgError::new(format!(
            "error: invalid value '{}' for '--style <style>'\n  \
             [possible values: name-only, asciidoc, fish, zsh]\n\n\
             For more information, try '--help'.",
            style
        )));
    }

    let sub = match subcommand.as_deref() {
        Some(x) => x,
        None => {
            return Err(StgError::new(
                "error: 'stg completion list' requires a subcommand but one was not provided\n  \
                 [subcommands: aliases, commands, commands-and-aliases, help]\n\n\
                 Usage: stg completion list [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
            ));
        }
    };

    let text = match sub {
        "aliases" => render_list("aliases", &style),
        "commands" => render_list("commands", &style),
        "commands-and-aliases" => render_list("commands-and-aliases", &style),
        "help" => {
            print!("{}", generic_list_help());
            return Ok(0);
        }
        other => {
            return Err(StgError::new(format!(
                "error: unrecognized subcommand '{}'\n\n\
                 Usage: stg completion list [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
                other
            )));
        }
    };

    if let Some(p) = output {
        fs::write(&p, &text)
            .map_err(|e| StgError::new(format!("error: cannot write `{}`: {}", p.display(), e)))?;
    } else {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(text.as_bytes());
    }
    Ok(0)
}

