fn render_asciidoc(cmds: &[(&str, &str, &str)], _include_admin: bool) -> String {
    let mut out = String::new();
    let mut current_group: Option<&str> = None;
    for (group, name, desc) in cmds {
        if Some(*group) != current_group {
            if current_group.is_some() {
                out.push('\n');
            }
            out.push_str(group);
            out.push('\n');
            for _ in 0..group.len() {
                out.push('~');
            }
            out.push_str("\n\n");
            current_group = Some(group);
        }
        out.push_str(&format!("linkstg:{}[]::\n    {}\n", name, desc));
    }
    out.push('\n');
    out
}

fn render_asciidoc_aliases(aliases: &[(&str, &str)]) -> String {
    let mut out = String::new();
    out.push_str("Aliases\n~~~~~~~\n\n");
    for (n, d) in aliases {
        out.push_str(&format!("linkstg:{}[]::\n    {}\n", n, d));
    }
    out.push('\n');
    out
}
