use crate::error::StgError;
use std::env;
use std::ffi::OsString;
use std::process::{Command, Stdio};

pub struct Alias {
    pub name: &'static str,
    pub target: &'static str,
    pub is_shell: bool,
    pub description: &'static str,
}

pub static ALIASES: &[Alias] = &[
    Alias {
        name: "add",
        target: "git -C \"$GIT_PREFIX\" add",
        is_shell: true,
        description: "Alias for shell command `git -C \"$GIT_PREFIX\" add`",
    },
    Alias {
        name: "mv",
        target: "git -C \"$GIT_PREFIX\" mv",
        is_shell: true,
        description: "Alias for shell command `git -C \"$GIT_PREFIX\" mv`",
    },
    Alias {
        name: "resolved",
        target: "git -C \"$GIT_PREFIX\" add",
        is_shell: true,
        description: "Alias for shell command `git -C \"$GIT_PREFIX\" add`",
    },
    Alias {
        name: "rm",
        target: "git -C \"$GIT_PREFIX\" rm",
        is_shell: true,
        description: "Alias for shell command `git -C \"$GIT_PREFIX\" rm`",
    },
    Alias {
        name: "status",
        target: "git status -s",
        is_shell: true,
        description: "Alias for shell command `git status -s`",
    },
];

pub fn find(name: &str) -> Option<&'static Alias> {
    ALIASES.iter().find(|a| a.name == name)
}

pub fn run_alias(alias: &Alias, args: Vec<OsString>) -> Result<u8, StgError> {
    if let Some(first) = args.first() {
        let s = first.to_string_lossy();
        if s == "-h" || s == "--help" {
            eprintln!("'{}' is aliased to '!{}'", alias.name, alias.target);
        }
    }

    let git_prefix = compute_git_prefix();
    let mut cmd = Command::new("sh");
    cmd.arg("-c");
    let mut script = String::from(alias.target);
    script.push_str(" \"$@\"");
    cmd.arg(script);
    cmd.arg(format!("stg-{}", alias.name));
    for a in &args {
        cmd.arg(a);
    }

    cmd.env("GIT_PREFIX", &git_prefix);
    cmd.stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit());

    match cmd.status() {
        Ok(st) => Ok(st.code().unwrap_or(1).clamp(0, 255) as u8),
        Err(e) => Err(StgError::new(format!(
            "error: failed to execute alias `{}`: {}",
            alias.name, e
        ))),
    }
}

fn compute_git_prefix() -> String {
    let out = Command::new("git").arg("rev-parse").arg("--show-prefix").output();
    if let Ok(o) = out {
        if o.status.success() {
            return String::from_utf8_lossy(&o.stdout).trim_end_matches('\n').to_string();
        }
    }
    let _ = env::current_dir();
    String::new()
}
