        ("Stack Manipulation", "squash", "Squash two or more patches into one"),
        ("Stack Manipulation", "uncommit", "Convert regular Git commits into StGit patches"),
        ("Stack Manipulation", "undo", "Undo the last command"),
        ("Stack Manipulation", "unhide", "Unhide hidden patches"),
        ("Administration", "completion", "Support for shell completions"),
        ("Administration", "help", "Print this message or the help of the given subcommand(s)"),
        ("Administration", "version", "Print version information and exit"),
    ];

    let aliases: &[(&str, &str)] = &[
        ("add", "Alias for shell command `git -C \"$GIT_PREFIX\" add`"),
        ("mv", "Alias for shell command `git -C \"$GIT_PREFIX\" mv`"),
        ("resolved", "Alias for shell command `git -C \"$GIT_PREFIX\" add`"),
        ("rm", "Alias for shell command `git -C \"$GIT_PREFIX\" rm`"),
        ("status", "Alias for shell command `git status -s`"),
    ];

    match (which, style) {
        ("aliases", "name-only") => aliases.iter().map(|a| format!("{}\n", a.0)).collect(),
        ("commands", "name-only") => commands.iter().map(|c| format!("{}\n", c.1)).collect(),
        ("commands-and-aliases", "name-only") => {
            let mut out = String::new();
            for c in commands {
                out.push_str(c.1);
                out.push('\n');
            }
            for a in aliases {
                out.push_str(a.0);
                out.push('\n');
            }
            out
        }
        ("commands", "asciidoc") => render_asciidoc(commands, false),
        ("aliases", "asciidoc") => render_asciidoc_aliases(aliases),
        ("commands-and-aliases", "asciidoc") => {
            let mut s = render_asciidoc(commands, false);
            s.push_str(&render_asciidoc_aliases(aliases));
            s
        }
        (_, _) => {
            // Placeholder for other styles: fish, zsh — produce empty for now
            String::new()
        }
    }
}

fn render_asciidoc(cmds: &[(&str, &str, &str)], _include_admin: bool) -> String {
    let mut out = String::new();
    let mut current_group: Option<&str> = None;
    for (group, name, desc) in cmds {
        if Some(*group) != current_group {
            if current_group.is_some() {
                out.push('\n');
            }
            out.push_str(group);
            out.push('\n');
            for _ in 0..group.len() {
                out.push('~');
            }
            out.push_str("\n\n");
            current_group = Some(group);
        }
        out.push_str(&format!("linkstg:{}[]::\n    {}\n", name, desc));
    }
    out.push('\n');
    out
}

fn render_asciidoc_aliases(aliases: &[(&str, &str)]) -> String {
    let mut out = String::new();
    out.push_str("Aliases\n~~~~~~~\n\n");
    for (n, d) in aliases {
        out.push_str(&format!("linkstg:{}[]::\n    {}\n", n, d));
    }
    out.push('\n');
    out
}
