const BASH_SCRIPT: &str = include_str!("data/completion_bash.sh");
const FISH_SCRIPT: &str = include_str!("data/completion_fish.fish");
const ZSH_SCRIPT: &str = include_str!("data/completion_zsh.zsh");

pub fn run(args: Vec<OsString>, _ctx: &Context) -> Result<u8, StgError> {
    let mut iter = args.into_iter().peekable();
    let mut output_path: Option<PathBuf> = None;
    let mut subcommand: Option<String> = None;

    while let Some(a) = iter.next() {
        let s = a.to_string_lossy().to_string();
        if s == "-h" {
            print!("{}", help_texts::find("completion").unwrap().short);
            return Ok(0);
        } else if s == "--help" {
            print!("{}", help_texts::find("completion").unwrap().full);
            return Ok(0);
        } else if s == "-o" || s == "--output" {
            if let Some(v) = iter.next() {
                output_path = Some(PathBuf::from(v));
            } else {
                return Err(StgError::new(
                    "error: a value is required for '--output <path>' but none was supplied\n\n\
                     For more information, try '--help'.",
                ));
            }
        } else if let Some(v) = s.strip_prefix("--output=") {
            output_path = Some(PathBuf::from(v));
        } else if let Some(v) = s.strip_prefix("-o") {
            if !v.is_empty() {
                output_path = Some(PathBuf::from(v));
            }
        } else if s == "--color" {
            if let Some(v) = iter.next() {
                crate::validate_color(&v.to_string_lossy())?;
            } else {
                return Err(StgError::new(
                    "error: a value is required for '--color <when>' but none was supplied\n  \
                     [possible values: auto, always, ansi, never]\n\n\
                     For more information, try '--help'.",
                ));
            }
        } else if let Some(v) = s.strip_prefix("--color=") {
            crate::validate_color(v)?;
        } else if s.starts_with('-') && s != "-" {
            return Err(StgError::new(format!(
                "error: unexpected argument '{}' found\n\n\
                 Usage: stg completion [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
                s
            )));
        } else {
            subcommand = Some(s);
            break;
        }
    }

    let remaining: Vec<OsString> = iter.collect();

    let sub = match subcommand {
        Some(s) => s,
        None => {
            return Err(StgError::new(
                "error: 'stg completion' requires a subcommand but one was not provided\n  \
                 [subcommands: bash, fish, zsh, list, man, help]\n\n\
                 Usage: stg completion [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
            ));
        }
    };

    match sub.as_str() {
        "bash" => script_subcommand("bash", BASH_SCRIPT, remaining, output_path),
        "fish" => script_subcommand("fish", FISH_SCRIPT, remaining, output_path),
        "zsh" => script_subcommand("zsh", ZSH_SCRIPT, remaining, output_path),
        "list" => list_subcommand(remaining, output_path),
        "man" => man_subcommand(remaining, output_path),
        "help" => completion_help(remaining),
        other => Err(StgError::new(format!(
            "error: unrecognized subcommand '{}'\n\n\
             Usage: stg completion [OPTIONS] <COMMAND>\n\n\
             For more information, try '--help'.",
            other
        ))),
    }
}

fn script_subcommand(
    name: &str,
    content: &str,
    args: Vec<OsString>,
    mut output: Option<PathBuf>,
) -> Result<u8, StgError> {
    let mut iter = args.into_iter();
    while let Some(a) = iter.next() {
        let s = a.to_string_lossy().to_string();
        if s == "-h" || s == "--help" {
            print!("{}", help_texts::find("completion").unwrap().full);
            return Ok(0);
        } else if s == "-o" || s == "--output" {
            if let Some(v) = iter.next() {
                output = Some(PathBuf::from(v));
            } else {
                return Err(StgError::new(format!(
                    "error: a value is required for '--output <path>' but none was supplied\n\n\
                     Usage: stg completion {} [OPTIONS]\n\n\
                     For more information, try '--help'.",
                    name
                )));
            }
        } else if let Some(v) = s.strip_prefix("--output=") {
            output = Some(PathBuf::from(v));
        } else if let Some(v) = s.strip_prefix("-o") {
            if !v.is_empty() {
                output = Some(PathBuf::from(v));
            }
        } else if s == "--color" {
            if let Some(v) = iter.next() {
                crate::validate_color(&v.to_string_lossy())?;
            }
        } else if let Some(v) = s.strip_prefix("--color=") {
            crate::validate_color(v)?;
        } else {
            return Err(StgError::new(format!(
                "error: unexpected argument '{}' found\n\n\
                 Usage: stg completion {} [OPTIONS]\n\n\
                 For more information, try '--help'.",
                s, name
            )));
        }
    }

    if let Some(p) = output {
        fs::write(&p, content)
            .map_err(|e| StgError::new(format!("error: cannot write `{}`: {}", p.display(), e)))?;
    } else {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(content.as_bytes());
    }
    Ok(0)
}

fn list_subcommand(args: Vec<OsString>, output_arg: Option<PathBuf>) -> Result<u8, StgError> {
    let mut iter = args.into_iter();
    let mut style = String::from("name-only");
    let mut output: Option<PathBuf> = output_arg;
    let mut subcommand: Option<String> = None;

    while let Some(a) = iter.next() {
        let s = a.to_string_lossy().to_string();
        if s == "-h" || s == "--help" {
            print!("{}", help_texts::find("completion").unwrap().full);
            return Ok(0);
        }
        if s == "--style" {
            if let Some(v) = iter.next() {
                style = v.to_string_lossy().into_owned();
            } else {
                return Err(StgError::new(
                    "error: a value is required for '--style <style>' but none was supplied\n\n\
                     For more information, try '--help'.",
                ));
            }
        } else if let Some(v) = s.strip_prefix("--style=") {
            style = v.to_string();
        } else if s == "-o" || s == "--output" {
            if let Some(v) = iter.next() {
                output = Some(PathBuf::from(v));
            }
        } else if let Some(v) = s.strip_prefix("--output=") {
            output = Some(PathBuf::from(v));
        } else if let Some(v) = s.strip_prefix("-o") {
            if !v.is_empty() {
                output = Some(PathBuf::from(v));
            }
        } else if s == "--color" {
            if let Some(v) = iter.next() {
                crate::validate_color(&v.to_string_lossy())?;
            }
        } else if let Some(v) = s.strip_prefix("--color=") {
            crate::validate_color(v)?;
        } else if s.starts_with('-') && s != "-" {
            return Err(StgError::new(format!(
                "error: unexpected argument '{}' found\n\n\
                 Usage: stg completion list [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
                s
            )));
        } else {
            subcommand = Some(s);
            break;
        }
    }

    if !matches!(style.as_str(), "name-only" | "asciidoc" | "fish" | "zsh") {
        return Err(StgError::new(format!(
            "error: invalid value '{}' for '--style <style>'\n  \
             [possible values: name-only, asciidoc, fish, zsh]\n\n\
             For more information, try '--help'.",
            style
        )));
    }

    let sub = match subcommand.as_deref() {
        Some(x) => x,
        None => {
            return Err(StgError::new(
                "error: 'stg completion list' requires a subcommand but one was not provided\n  \
                 [subcommands: aliases, commands, commands-and-aliases, help]\n\n\
                 Usage: stg completion list [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
            ));
        }
    };

    let text = match sub {
        "aliases" => render_aliases(&style),
        "commands" => render_commands(&style),
        "commands-and-aliases" => {
            let mut c = render_commands(&style);
            let a = render_aliases(&style);
            match style.as_str() {
                "asciidoc" => {
                    // commands asciidoc ends with blank line; append aliases block
                    c.push_str(&a);
                    c
                }
                _ => {
                    c.push_str(&a);
                    c
                }
            }
        }
        "help" => {
            print!("{}", help_texts::find("completion").unwrap().full);
            return Ok(0);
        }
        other => {
            return Err(StgError::new(format!(
                "error: unrecognized subcommand '{}'\n\n\
                 Usage: stg completion list [OPTIONS] <COMMAND>\n\n\
                 For more information, try '--help'.",
                other
            )));
        }
    };

    if let Some(p) = output {
        fs::write(&p, &text)
            .map_err(|e| StgError::new(format!("error: cannot write `{}`: {}", p.display(), e)))?;
    } else {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(text.as_bytes());
    }
    Ok(0)
}

