        ("rm", "Alias for shell command `git -C \"$GIT_PREFIX\" rm`"),
        ("status", "Alias for shell command `git status -s`"),
    ]
}

fn render_commands(style: &str) -> String {
    let cmds = commands_data();
    match style {
        "name-only" => {
            let mut items: Vec<(&str, &str)> = cmds.iter().map(|(_, n, _)| (*n, "")).collect();
            // Separate help, then sort rest alphabetically, then append help at end
            let help_idx = items.iter().position(|(n, _)| *n == "help");
            let help = help_idx.map(|i| items.remove(i));
            items.sort_by(|a, b| a.0.cmp(b.0));
            let mut out = String::new();
            for (n, _) in &items {
                out.push_str(n);
                out.push('\n');
            }
            if let Some((n, _)) = help {
                out.push_str(n);
                out.push('\n');
            }
            out
        }
        "fish" => {
            let mut items: Vec<(&str, &str)> = cmds.iter().map(|(_, n, d)| (*n, *d)).collect();
            let help_idx = items.iter().position(|(n, _)| *n == "help");
            let help = help_idx.map(|i| items.remove(i));
            items.sort_by(|a, b| a.0.cmp(b.0));
            let mut out = String::new();
            for (n, d) in &items {
                out.push_str(n);
                out.push('\t');
                out.push_str(d);
                out.push('\n');
            }
            if let Some((n, d)) = help {
                out.push_str(n);
                out.push('\t');
                out.push_str(d);
                out.push('\n');
            }
            out
        }
        "zsh" => {
            let mut items: Vec<(&str, &str)> = cmds.iter().map(|(_, n, d)| (*n, *d)).collect();
            let help_idx = items.iter().position(|(n, _)| *n == "help");
            let help = help_idx.map(|i| items.remove(i));
            items.sort_by(|a, b| a.0.cmp(b.0));
            let mut out = String::new();
            for (n, d) in &items {
                out.push_str(n);
                out.push(':');
                out.push_str(d);
                out.push('\n');
            }
            if let Some((n, d)) = help {
                out.push_str(n);
                out.push(':');
                out.push_str(d);
                out.push('\n');
            }
            out
        }
        "asciidoc" => {
            let mut out = String::new();
            let mut current_group: Option<&str> = None;
            for (g, n, d) in cmds {
                if Some(*g) != current_group {
                    if current_group.is_some() {
                        out.push('\n');
                    }
                    out.push_str(g);
                    out.push('\n');
                    for _ in 0..g.len() {
                        out.push('~');
                    }
                    out.push_str("\n\n");
                    current_group = Some(g);
                }
                out.push_str(&format!("linkstg:{}[]::\n    {}\n", n, d));
            }
            out.push('\n');
            out
        }
        _ => String::new(),
    }
}

fn render_aliases(style: &str) -> String {
    let aliases = aliases_data();
    match style {
        "name-only" => {
            let mut out = String::new();
            for (n, _) in aliases {
                out.push_str(n);
                out.push('\n');
            }
            out
        }
        "fish" => {
            let mut out = String::new();
            for (n, d) in aliases {
                out.push_str(n);
                out.push('\t');
                out.push_str(d);
                out.push('\n');
            }
            out
        }
        "zsh" => {
            let mut out = String::new();
            for (n, d) in aliases {
                out.push_str(n);
                out.push(':');
                out.push_str(d);
                out.push('\n');
            }
            out
        }
        "asciidoc" => {
            let mut out = String::new();
            out.push_str("Aliases\n~~~~~~~\n\n");
            for (n, d) in aliases {
                out.push_str(&format!("{}::\n    {}\n", n, d));
            }
            out
        }
        _ => String::new(),
    }
}
