            full: include_str!(concat!("help/", $dir, "_full/", $name, ".txt")),
            short: include_str!(concat!("help/", $dir, "_short/", $name, ".txt")),
        }
    };
}

pub static COMMANDS: &[Entry] = &[
    e!("diff"), e!("files"), e!("id"), e!("log"), e!("name"), e!("show"),
    e!("edit"), e!("fold"), e!("new"), e!("refresh"), e!("rename"), e!("spill"), e!("sync"),
    e!("email"), e!("export"), e!("next"), e!("patches"), e!("prev"), e!("series"), e!("top"),
    e!("branch"), e!("clean"), e!("commit"), e!("delete"), e!("float"), e!("goto"), e!("hide"),
    e!("import"), e!("init"), e!("pick"), e!("pop"), e!("pull"), e!("push"), e!("rebase"),
    e!("redo"), e!("repair"), e!("reset"), e!("sink"), e!("squash"), e!("uncommit"), e!("undo"),
    e!("unhide"), e!("completion"), e!("version"),
    e!("add"), e!("mv"), e!("resolved"), e!("rm"), e!("status"),
];

pub fn find(name: &str) -> Option<&'static Entry> {
    COMMANDS.iter().find(|e| e.name == name)
}

// Completion sub-subcommand helps
pub static COMPLETION_BASH_FULL: &str = include_str!("help/completion_full/bash.txt");
pub static COMPLETION_BASH_SHORT: &str = include_str!("help/completion_short/bash.txt");
