pub static COMPLETION_FISH_SHORT: &str = include_str!("help/completion_short/fish.txt");
pub static COMPLETION_ZSH_FULL: &str = include_str!("help/completion_full/zsh.txt");
pub static COMPLETION_ZSH_SHORT: &str = include_str!("help/completion_short/zsh.txt");
pub static COMPLETION_LIST_FULL: &str = include_str!("help/completion_full/list.txt");
pub static COMPLETION_LIST_SHORT: &str = include_str!("help/completion_short/list.txt");
