pub static COMPLETION_MAN_SHORT: &str = include_str!("help/completion_short/man.txt");

pub static COMPLETION_LIST_ALIASES_FULL: &str =
    include_str!("help/completion_list_full/aliases.txt");
pub static COMPLETION_LIST_ALIASES_SHORT: &str =
