pub static COMPLETION_LIST_COMMANDS_AND_ALIASES_FULL: &str =
    include_str!("help/completion_list_full/commands-and-aliases.txt");
pub static COMPLETION_LIST_COMMANDS_AND_ALIASES_SHORT: &str =
    include_str!("help/completion_list_short/commands-and-aliases.txt");

pub fn completion_sub_full(name: &str) -> Option<&'static str> {
    match name {
        "bash" => Some(COMPLETION_BASH_FULL),
        "fish" => Some(COMPLETION_FISH_FULL),
        "zsh" => Some(COMPLETION_ZSH_FULL),
        "list" => Some(COMPLETION_LIST_FULL),
        "man" => Some(COMPLETION_MAN_FULL),
        _ => None,
    }
}
pub fn completion_sub_short(name: &str) -> Option<&'static str> {
    match name {
        "bash" => Some(COMPLETION_BASH_SHORT),
        "fish" => Some(COMPLETION_FISH_SHORT),
        "zsh" => Some(COMPLETION_ZSH_SHORT),
        "list" => Some(COMPLETION_LIST_SHORT),
        "man" => Some(COMPLETION_MAN_SHORT),
        _ => None,
    }
}
pub fn completion_list_sub_full(name: &str) -> Option<&'static str> {
    match name {
        "aliases" => Some(COMPLETION_LIST_ALIASES_FULL),
        "commands" => Some(COMPLETION_LIST_COMMANDS_FULL),
        "commands-and-aliases" => Some(COMPLETION_LIST_COMMANDS_AND_ALIASES_FULL),
        _ => None,
    }
}
pub fn completion_list_sub_short(name: &str) -> Option<&'static str> {
    match name {
        "aliases" => Some(COMPLETION_LIST_ALIASES_SHORT),
        "commands" => Some(COMPLETION_LIST_COMMANDS_SHORT),
        "commands-and-aliases" => Some(COMPLETION_LIST_COMMANDS_AND_ALIASES_SHORT),
        _ => None,
    }
}
