                style = v.to_string_lossy().into_owned();
            } else {
                return Err(StgError::new(
                    "error: a value is required for '--style <style>' but none was supplied\\n\\n\\
                     For more information, try '--help'.",
                ));
            }
        } else if let Some(v) = s.strip_prefix("--style=") {
            style = v.to_string();
        } else if s == "-o" || s == "--output" {
            if let Some(v) = iter.next() {
                output = Some(PathBuf::from(v));
            }
        } else if let Some(v) = s.strip_prefix("--output=") {
            output = Some(PathBuf::from(v));
        } else if let Some(v) = s.strip_prefix("-o") {
            if !v.is_empty() {
                output = Some(PathBuf::from(v));
            }
        } else if s == "--color" {
            if let Some(v) = iter.next() {
                crate::validate_color(&v.to_string_lossy())?;
            }
        } else if let Some(v) = s.strip_prefix("--color=") {
            crate::validate_color(v)?;
        } else if s.starts_with('-') && s != "-" {
            return Err(StgError::new(format!(
                "error: unexpected argument '{}' found\\n\\n\\
                 Usage: stg completion list [OPTIONS] <COMMAND>\\n\\n\\
                 For more information, try '--help'.",
                s
            )));
        } else {
            if positionals.is_empty() && s == "help" {
                in_help_context = true;
            }
            positionals.push(s);
        }
    }

    // Handle help requests based on positionals
    if help_mode.is_some() {
        let full = help_mode == Some(true);
        let first = positionals.first().map(|s| s.as_str());
        match first {
            None | Some("help") => {
                print!("{}", if full { help_texts::COMPLETION_LIST_FULL } else { help_texts::COMPLETION_LIST_SHORT });
                return Ok(0);
            }
            Some(name) => {
                if let Some(txt) = if full { help_texts::completion_list_sub_full(name) } else { help_texts::completion_list_sub_short(name) } {
                    print!("{}", txt);
                    return Ok(0);
                } else {
                    return Err(StgError::new(format!(
                        "error: unrecognized subcommand '{}'\\n\\n\\
                         Usage: stg completion list [OPTIONS] <COMMAND>\\n\\n\\
                         For more information, try '--help'.",
                        name
                    )));
                }
            }
        }
    }

    if !matches!(style.as_str(), "name-only" | "asciidoc" | "fish" | "zsh") {
        return Err(StgError::new(format!(
            "error: invalid value '{}' for '--style <style>'\\n  \\
             [possible values: name-only, asciidoc, fish, zsh]\\n\\n\\
             For more information, try '--help'.",
            style
        )));
    }

    let sub = match positionals.first().map(|s| s.as_str()) {
        Some(x) => x,
        None => {
            return Err(StgError::new(
                "error: 'stg completion list' requires a subcommand but one was not provided\\n  \\
                 [subcommands: aliases, commands, commands-and-aliases, help]\\n\\n\\
                 Usage: stg completion list [OPTIONS] <COMMAND>\\n\\n\\
                 For more information, try '--help'.",
            ));
        }
    };

    let text = match sub {
        "aliases" => render_aliases(&style),
        "commands" => render_commands(&style),
        "commands-and-aliases" => {
            let mut c = render_commands(&style);
            let a = render_aliases(&style);
            c.push_str(&a);
            c
        }
        "help" => {
            let target = positionals.get(1).map(|s| s.as_str());
            match target {
                None => {
                    print!("{}", help_texts::COMPLETION_LIST_FULL);
                    return Ok(0);
                }
                Some("help") => {
                    if positionals.len() > 2 {
                        let extra = positionals[2].as_str();
                        return Err(StgError::new(format!(
                            "error: unrecognized subcommand '{}'\\n\\n\\
                             Usage: stg completion list help [COMMAND]...",
                            extra
                        )));
                    }
                    print!("{}", help_texts::COMPLETION_LIST_HELP_HELP);
                    return Ok(0);
                }
                Some(name) => {
                    if let Some(txt) = help_texts::completion_list_sub_full(name) {
                        print!("{}", txt);
                        return Ok(0);
                    } else {
                        return Err(StgError::new(format!(
                            "error: unrecognized subcommand '{}'\\n\\n\\
                             Usage: stg completion list [OPTIONS] <COMMAND>\\n\\n\\
                             For more information, try '--help'.",
                            name
                        )));
                    }
                }
            }
        }
        other => {
            return Err(StgError::new(format!(
                "error: unrecognized subcommand '{}'\\n\\n\\
                 Usage: stg completion list [OPTIONS] <COMMAND>\\n\\n\\
                 For more information, try '--help'.",
                other
            )));
        }
    };

    if let Some(p) = output {
        fs::write(&p, &text)
            .map_err(|e| StgError::new(format!("error: cannot write `{}`: {}", p.display(), e)))?;
    } else {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = lock.write_all(text.as_bytes());
    }
    Ok(0)
}

